insert into public.essentials (name, category, subcategory, address, neighborhood, description, image, open_hours, maps_link,
                               latitude, longitude, hidden, import_source, city_id, phone, website, is_24h, source, source_url,
                               verification_status, attrs)
select n.name, n.category, n.subcategory, n.address, n.neighborhood, null, null, n.open_hours, null,
       n.lat::double precision, n.lon::double precision, true, 'osm',
       (select id from public.cities where slug = 'madrid'),
       n.phone, n.website, n.is_24h::boolean, 'osm', n.source_url, 'unverified', n.attrs::jsonb
from nuevos n
where not exists (
  select 1 from public.essentials e
  where e.category = n.category
    and nullif(e.latitude::text, '') is not null and nullif(e.longitude::text, '') is not null
    and (
      111320 * sqrt(power(nullif(e.latitude::text, '')::float8 - n.lat::float8, 2)
                  + power((nullif(e.longitude::text, '')::float8 - n.lon::float8) * cos(radians(n.lat::float8)), 2)) < 15
      or (
        111320 * sqrt(power(nullif(e.latitude::text, '')::float8 - n.lat::float8, 2)
                    + power((nullif(e.longitude::text, '')::float8 - n.lon::float8) * cos(radians(n.lat::float8)), 2)) < 150
        and public.noctua_norm_venue_name(e.name) = public.noctua_norm_venue_name(n.name)
      )
    )
);

-- Comprobación: lo de Madrid de este lote, por categoría (todo debe salir oculto).
select category, count(*) as filas, count(*) filter (where hidden = false) as visibles
from public.essentials
where attrs->>'lote' = 'madrid-osm-20261115'
group by category
order by category;
